fields.InputDefinition:
{
  "goal": "You are logged in at http://localhost:4200. Click the user avatar button in the TOP-RIGHT corner of the header to open the user menu. Then perform these sub-actions IN ORDER, and as you complete each set \"checkpointReached\" to the exact checkpoint name shown: (1) theme-toggle — find the theme toggle row in the user menu (a sun/moon switch with a label like 'Theme' or 'Dark Mode') and click it to flip the theme, confirming the entire application visibly re-skins (light interface switches to a dark background with light text, or vice-versa) and the toggle reflects the new state, then click it again to flip back; (2) about-dialog — reopen the user menu if needed, confirm it shows a header with your user name/email plus menu items, then click the 'About' item and confirm an About dialog opens showing MemberJunction information such as a version number (you do NOT need to do anything inside the dialog — close it); (3) sign-out — reopen the user menu and click the 'Sign Out' (logout) item, confirming the app tears down the session and returns to the sign-in / login screen (an auth prompt or login button appears); you do NOT need to log back in. Do sign-out LAST, since it ends the session. Keep going until all sub-actions are done. Pages can take 10-30s to load in this resource-constrained environment — wait, don't navigate away.",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}

fields.ExpectedOutcomes:
{
  "goalCompleted": true,
  "finalUrlPattern": "^http://localhost:4200",
  "minConfidence": 0.7,
  "maxSteps": 45,
  "checkpoints": [
    {
      "name": "theme-toggle",
      "instruction": "flip the theme light/dark from the user menu",
      "visualCriteria": [
        "The user avatar menu opens and shows a theme toggle control (sun/moon switch), clicking it visibly changes the app's color scheme (light<->dark) across the header and page background, and the toggle switch position/icon updates to reflect the newly applied theme"
      ]
    },
    {
      "name": "about-dialog",
      "instruction": "open the About dialog from the user menu",
      "visualCriteria": [
        "The user avatar menu displays a user identity header (name and/or email) plus menu items including an 'About' item, and clicking 'About' opens a dialog with MemberJunction/version information"
      ]
    },
    {
      "name": "sign-out",
      "instruction": "sign out and land on the login screen",
      "visualCriteria": [
        "Clicking the 'Sign Out' / logout item leaves the authenticated Explorer shell (header/tabs no longer shown) and presents a login / sign-in screen or auth prompt"
      ]
    }
  ]
}
